from src.lexicore.tokenization.bpe_tokenizer import BPETokenizer


with open(
    "src/lexicore/data/word2vec_data.txt",
    "r",
    encoding="utf-8"
) as file:
    corpus = file.read()


bpe = BPETokenizer(
    vocab_size=100
)

bpe.fit(corpus)


print("=" * 50)
print("VOCAB SIZE")
print("=" * 50)

print(len(bpe.vocab))


print("\n" + "=" * 50)
print("LEARNED MERGES")
print("=" * 50)

for i, merge in enumerate(bpe.merges[:20], start=1):
    print(f"{i:02d}. {merge}")


print("\n" + "=" * 50)
print("TOKENIZATION")
print("=" * 50)

text = """
Employees access internal documents through the company portal.
The database stores customer information.
"""

tokens = bpe.tokenize(text)

print(tokens)